// KeyaraAPI Pages Worker (auto-generated by tunnel.sh/autodeploy)
const BACKEND = "https://copyrights-newfoundland-appropriations-richards.trycloudflare.com";

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    // Static site: / , /index.html , favicon
    if (url.pathname === "/" || url.pathname === "/index.html" || url.pathname === "/favicon.ico") {
      return env.ASSETS.fetch(request);
    }
    // Sab kuch backend (tunnel) pe proxy
    const upstream = BACKEND + url.pathname + url.search;
    const req = new Request(upstream, request);
    const resp = await fetch(req);
    const r = new Response(resp.body, resp);
    r.headers.set("access-control-allow-origin", "*");
    r.headers.set("access-control-allow-headers", "*");
    r.headers.set("x-keyara-proxy", "pages");
    return r;
  }
};
